{"type": "file", "encoding": "utf-8", "name": "NotificationToggleButton.cs", "path": "Assets/Scripts/Notifications/NotificationToggleButton.cs", "size": 3340, "sha": "dddccbfd42f5fbf4162c81c678009df118d564bf", "content": "using TMPro;
using UnityEngine;

namespace Notifications
{
    public class NotificationToggleButton : MonoBehaviour
    {
        [SerializeField]
        private GameObject _enableSettingsPopup;
        [SerializeField]
        private Match3DButton _redirectToSettingsButton;
        [SerializeField]
        private GameObject _settingPopUp;
        [SerializeField]
        private GameObject _settingScreen;

        [Header("Assign in Inspector")]
        [SerializeField] private GameObject _toggleBtnON;
        [SerializeField] private GameObject _toggleBtnOFF;
        [SerializeField] private TMP_Text _textBtnOFF;
        [SerializeField] private Match3DButton _notificationBtn;

        [Header("State Colors")]
        [SerializeField] private Color32 _offStateColor = new Color32(0x72, 0x21, 0x22, 0xFF);
        [SerializeField] private Color32 _onStateColor = new Color32(0x2A, 0x4A, 0x65, 0xFF);


        private void OnEnable()
        {
            UpdateVisualToggleButtons(PlayerPrefs.GetString(NotificationManager.NotificationsPermission) == "PermissionGranted");
        }

        private void Start()
        {
            if (_notificationBtn != null)
                _notificationBtn.onClick.AddListener(OnNotificationButtonClicked);
            if (_redirectToSettingsButton != null)
                _redirectToSettingsButton.onClick.AddListener(RequestNotificationPermission);
        }
        private void OnNotificationButtonClicked()
        {
            if (NotificationManager.Instance == null) return;

            if (NotificationManager.Instance.NotificationsEnabled)
            {
                // Disable notifications
                UpdateVisualToggleButtons(false);
                NotificationManager.Instance.DisableNotifications();
            }
            else
            {
                if (PlayerPrefs.GetString(NotificationManager.NotificationsPermission) == "PermissionGranted")
                {
                    // Cannot request permission again, inform the user to go to settings
                    UpdateVisualToggleButtons(true);
                    NotificationManager.Instance.EnableNotifications();
                }
                else
                {
                    // Request notification permissions

                    if (PlayerPrefs.HasKey(NotificationManager.FirstNotificationsPermission))
                    {
                        ShowSettingsPopup();
                    }
                    else 
                    { 
                        NotificationManager.Instance.Init(); 
                    }
                }
            }
        }

        public void UpdateVisualToggleButtons(bool isEnable)
        {
            _toggleBtnON.SetActive(isEnable);
            _toggleBtnOFF.SetActive(!isEnable);

            _textBtnOFF.color = isEnable ? _onStateColor : _offStateColor;
        }

        public void ShowSettingsPopup()
        {
            _enableSettingsPopup.SetActive(true);
        }

        public void RequestNotificationPermission()
        {
            _enableSettingsPopup.SetActive(false);
            _settingPopUp.SetActive(false);
            if (NotificationManager.Instance == null) return;
            NotificationManager.Instance.RequestNotificationPermission();
        }
    }
}
