namespace Utils
{
    public class LevelVariantManager : SingletonMonoBehaviour<LevelVariantManager>
    {
        [field: SerializeField] public ETestVariant TestVariant { get; private set; } = ETestVariant.Default;

        [Header("Start Levels")]
        [SerializeField] private LevelVariantAsset _forcedLevelsCount;

        [Header("Feature Unlock Levels")]
        [SerializeField] private LevelVariantAsset _zombieLaneUnlockLevel;
        [SerializeField] private LevelVariantAsset _questsUnlockLevel;
        [SerializeField] private LevelVariantAsset _plagueRaceUnlockLevel;
        [SerializeField] private LevelVariantAsset _leaderboardsUnlockLevel;
        [SerializeField] private LevelVariantAsset _endlessUnlockLevel;
        [SerializeField] private LevelVariantAsset _seasonPassUnlockLevel;
        [SerializeField] private LevelVariantAsset _infiniteBossUnlockLevel;
        [SerializeField] private LevelVariantAsset _firstTutorialFinishedLevel;
        [SerializeField] private LevelVariantAsset _firstZombieLaneTargetReward;
        [SerializeField] public LevelVariantAsset _collectAndWinUnlockLevel;

        [Header("Tutorial Unlock Levels")]
        [SerializeField] private LevelVariantAsset _catapultTutorialUnlockLevel;
        [SerializeField] private LevelVariantAsset _broomTutorialUnlockLevel;
        [SerializeField] private LevelVariantAsset _tornadoTutorialUnlockLevel;
        [SerializeField] private LevelVariantAsset _taserTutorialUnlockLevel;
        [SerializeField] private LevelVariantAsset _winStreakBoostUnlockLevel;

        // Start Levels
        public static int ForcedLevelsCount => GetLevel(Instance?._forcedLevelsCount, 2);

        // Feature Unlock Levels
        public static int ZombieLaneUnlockLevel => GetLevel(Instance?._zombieLaneUnlockLevel, 5);
        public static int QuestsUnlockLevel => GetLevel(Instance?._questsUnlockLevel, 20);
        public static int PlagueRaceUnlockLevel => GetLevel(Instance?._plagueRaceUnlockLevel, 26);
        public static int LeaderboardsUnlockLevel => GetLevel(Instance?._leaderboardsUnlockLevel, 22);
        public static int EndlessUnlockLevel => GetLevel(Instance?._endlessUnlockLevel, 24);
        public static int SeasonPassUnlockLevel => GetLevel(Instance?._seasonPassUnlockLevel, 30);
        public static int InfiniteBossUnlockLevel => GetLevel(Instance?._infiniteBossUnlockLevel, 24);
        public static int FirstTutorialFinished => GetLevel(Instance?._firstTutorialFinishedLevel, 20);
        public static int FirstZombieLaneTargetReward => GetLevel(Instance?._firstZombieLaneTargetReward, 4);
        public static int CollectAndWinUnlockLevel => GetLevel(Instance?._collectAndWinUnlockLevel, 14);

        // Tutorial Unlock Levels
        public static int CatapultTutorialUnlockLevel => GetLevel(Instance?._catapultTutorialUnlockLevel, 7);
        public static int BroomTutorialUnlockLevel => GetLevel(Instance?._broomTutorialUnlockLevel, 9);
        public static int TornadoTutorialUnlockLevel => GetLevel(Instance?._tornadoTutorialUnlockLevel, 11);
        public static int TaserTutorialUnlockLevel => GetLevel(Instance?._taserTutorialUnlockLevel, 13);
        public static int WinStreakBoostUnlockLevel => GetLevel(Instance?._winStreakBoostUnlockLevel, 19);

        private static int GetLevel(LevelVariantAsset asset, int fallbackValue)
        {
            if (asset == null)
            {
                Debug.LogError("Asset is null");
                return fallbackValue;
            }

