    public void OnWeeklyEndCallback(DateTime value)
    {
        StartCoroutine(HandleWeeklyEnd());
    }

    private IEnumerator HandleWeeklyEnd(bool getData = true)
    {
        if (getData) yield return GetEventDataRoutine(false);
        if (LeaderboardMenu.Instance)
        {
            if (LeaderboardMenu.Instance.gameObject.activeSelf)
            {
                LeaderboardMenu.Instance.gameObject.SetActive(false);
                LeaderboardMenu.Instance.gameObject.SetActive(true);
            }
        }

        var rankedPlayers = Blob.WeeklyUsers.OrderByDescending(user => user.Score).ToList();
        var player = rankedPlayers.First(user => user.IsPlayer);
        var playerRank = rankedPlayers.IndexOf(player) + 1;

        HasBeenPromoted = playerRank <= PromotionThreshold;

        var menu = LeaderboardMenu.Instance;

        if (!HasBeenPromoted)
        {
            yield return JoinWeeklyLeague();
        }

        if (menu != null && menu.gameObject.activeSelf)
        {
            menu.WeekHasEnded(HasBeenPromoted);
        }     
    }

    public void Add100Points()
    {
        WeeklyPlayerData.Score += 100;
        AllTimePlayerData.Score += 100;
        AllTimePlayerData.AllTimeStarsScore += 100;
    }

    public void Remove100Points()
    {
        WeeklyPlayerData.Score -= 100;
        AllTimePlayerData.Score -= 100;
        AllTimePlayerData.AllTimeStarsScore -= 100;
    }

    public void ResetNameChangeTries()
    {
        PlayerPrefs.SetInt(PlayerCharacterSelectManager.NameChangesAvailableKey, 3);
    }

    public void DebugBlob()
    {
        Debug.Log("AAAA Printed Blob\n " + JsonConvert.SerializeObject(Blob, Formatting.Indented));
    }

    public void ForceWeeklyJoin()
    {
        StartCoroutine(JoinWeeklyLeague());
    }

    public void ForceGetAllData()
    {
        StartCoroutine(GetEventDataRoutine(false));
    }
